def calcular_media(*notas):
    """Recebe qualquer quantidade de notas e devolve a média."""
    return sum(notas) / len(notas)

def situacao(media, corte=7.0):
    """Devolve 'Aprovado' ou 'Recuperação' conforme a nota de corte."""
    if media >= corte:
        return "Aprovado"
    return "Recuperação"

def linha():
    print("-" * 30)

def exibir_aluno(nome, media):
    print(f"{nome:<10} {media:>5.2f}   {situacao(media)}")

turma = {
    "Ana": calcular_media(8.5, 7.0, 9.0),
    "Carlos": calcular_media(6.0, 5.5),
    "Beatriz": calcular_media(9.0, 8.5, 10.0, 9.5),
}

linha()
for nome, media in sorted(turma.items(), key=lambda item: item[1], reverse=True):
    exibir_aluno(nome, media)
linha()

aprovados = list(filter(lambda n: situacao(turma[n]) == "Aprovado", turma))
print(f"Aprovados: {', '.join(aprovados)}")

