def converter_temperatura(valor, para="F"):
    if para == "F":
        return valor * 9 / 5 + 32
    return (valor - 32) * 5 / 9

print(converter_temperatura(30))         # 86.0
print(converter_temperatura(86, "C"))    # 30.0

